Fix this JavaScript checkout so retrying the same key returns the original receipt without a second charge. Different keys must still charge separately. Return ONLY plain JavaScript starting with function createCheckout(), no markdown, imports, exports, networking or explanations. Preserve the pay(key) and charges interface.
function createCheckout() {
  const receipts = new Map(); let charges = 0;
  return {
    pay(key) { const receipt = { id: 'receipt-' + (++charges), key }; receipts.set(key, receipt); return receipt; },
    get charges() { return charges; }
  };
}

