rawOutput:
function createCheckout() {
  const receipts = new Map();
  let charges = 0;
  return {
    pay(key) {
      if (receipts.has(key)) {
        return receipts.get(key);
      }
      const receipt = { id: 'receipt-' + (++charges), key };
      receipts.set(key, receipt);
      return receipt;
    },
    get charges() {
      return charges;
    }
  };
}
